import"./chunk-2NFLSA4Y.js";var s={pendulum:{theory:{concept:"[[A simple pendulum is a small, heavy body (the bob) hanging from a fixed point on a light, inextensible string and swinging under gravity.]] For small swings the period depends only on the length of the string and on the acceleration of gravity, T = 2\u03C0 \xB7 \u221A(L / g) \u2014 not on the mass of the bob or on the amplitude. For large swings the period becomes noticeably longer."},section:{what:{title:"Why does a pendulum swing?",text:"When the bob is pulled aside, gravity pulls it back towards the lowest point. It arrives there moving fast, so it overshoots to the other side, slows down, stops for an instant and comes back. Without air resistance this would go on forever."},period:{title:"The period",text:"[[The period T is the time for one full swing, there and back.]] To measure it well, time several swings and divide: T = t / N. A longer string gives a longer period: four times the length gives twice the period. Weaker gravity, like on the Moon, also makes the pendulum swing more slowly."},notMass:{title:"Heavy or light \u2014 the same rhythm",text:"A heavy bob is pulled harder by gravity, but it is also harder to speed up. [[The two effects cancel exactly, so the period does not depend on the mass.]] Galileo noticed that the period hardly depends on the size of the swing either, as long as the swing is small."},energy:{title:"Energy changes form",text:"At the highest point the bob is momentarily at rest: all its energy is potential energy (m\xB7g\xB7h). At the lowest point it is fastest: the energy is kinetic (\xBD\xB7m\xB7v\xB2). In between the energy keeps changing from one form to the other, while the total stays the same. Air resistance slowly turns it into heat, so the swings shrink."},bigSwings:{title:"When the simple formula fails",text:"[[The formula T = 2\u03C0\xB7\u221A(L/g) is exact only for small swings.]] For large swings the period gets longer: about 2 % longer at 30\xB0, 7 % at 60\xB0 and 18 % at 90\xB0. The simulation solves the full equation of motion, so you can see the difference yourself."},example:{title:"In real life",text:"Pendulum clocks use a 1 m pendulum: each swing to one side takes one second. Swings at a playground, a crane's hook or a hanging lamp all behave like pendulums. Scientists even use pendulums to measure g at different places on the Earth."},check:{title:"Check your understanding",text:"A pendulum makes 10 full swings in 20 s. What is its period? (2 s.) What happens to the period if you make the string four times longer? (It doubles.) Does a heavier bob swing faster? (No.) Try each answer in the simulation."}},formula:{measure:"Period measured from N full swings in time t",period:"Period of a pendulum with small swings",frequency:"Frequency: full swings per second",energy:"Energy: height at the turning point becomes speed at the bottom",motion:"Equation of motion for any amplitude"},variable:{period:"Period (one full swing)",length:"Length of the string",swings:"Number of full swings",angle:"Angle from the vertical"},assumption:{point:"The bob is a point mass: all its mass is at one point at the end of the string.",string:"The string has no mass, does not stretch and stays straight, so swings are limited to 90\xB0.",air:"There is no air resistance and no friction at the pivot unless you add damping (Advanced).",smallAngle:"The formula T = 2\u03C0\xB7\u221A(L/g) holds for small swings only; the simulation itself uses the full equation for any amplitude.",scale:"The bob is drawn larger than a real one so that it stays visible."},param:{length:"String length",amplitude:"Release angle",mass:"Mass of the bob",gravity:"Gravity",damping:"Air resistance",timeStep:"Simulation timestep"},hint:{length:"Measured from the pivot to the centre of the bob.",amplitude:"How far you pull the bob aside before letting go.",mass:"Does a heavier bob swing faster? Try it.",damping:"Air resistance slowly takes energy away, so the swings shrink."},measure:{swings:"Full swings",angle:"Angle from the vertical",period:"Period (measured)",smallAnglePeriod:"Period from the formula",frequency:"Frequency",amplitude:"Current swing size",tension:"String tension",exactPeriod:"Exact period for this release angle"},view:{swings:"Full swings: {swings} / {total}",period:"Full swings: {swings} / {total} \xB7 T = {period}",angleOption:"Angle marker",heightOption:"Height"},graph:{angle:"Angle against time",energy:"Energy against time"},challenge:{seconds:{title:"Seconds pendulum",description:"Build a pendulum with a period of 2 s, so that each swing to one side takes exactly one second \u2014 like in a pendulum clock.",hint:"On Earth the string must be about 1 m long."},slow:{title:"Slow swing",description:"Make the period at least 3 s.",hint:"A longer string swings more slowly."},fast:{title:"Quick swing",description:"Make the period 1 s or shorter.",hint:"Make the string much shorter. Does the release angle help?"},moon:{title:"A clock on the Moon",description:"On the Moon (g = 1.62 m/s\xB2), build a pendulum with a period of 2 s.",hint:"Weaker gravity makes the pendulum slower, so the string must be shorter than on Earth."},bigSwing:{title:"Beyond small swings",description:"Make the measured period at least 7 % longer than the formula T = 2\u03C0\xB7\u221A(L/g) predicts.",hint:"The formula is for small swings. Release the bob from a large angle."},fade:{title:"Fading out",description:"Add air resistance so that the swing dies out before five full swings.",hint:"Air resistance affects a light bob more. Try a small mass and strong damping."}}}},i={sim:s};export{i as default,s as sim};
